def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        freq = defaultdict(set)
        pos = 0

        def wrapper(*args, **kwargs):
            nonlocal pos
            key = (args, frozenset(kwargs))
            if key in cache:
                value = cache[key]
            else:
                value = func(*args, **kwargs)
                cache[key] = value
                freq[key].add(pos)
                pos += 1
                if len(freq) > maxsize:
