def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Updates a partial `last_applied_manifest` list from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): The partial `last_applied_manifest` being updated.
        observer_schema (list): The partial `observer_schema`.
        response (list): The partial response from the Kubernetes API.
    """
    # Go through all observed fields in the schema and initialize their value in the last_applied_manifest if they are not yet present
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest.append(field)
    for i, response_field in enumerate(response):
        if i < len(last_applied_manifest):
            # If the current field in the response is the same as in the last_applied_manifest, then update its value
            if response_field == last_applied_manifest[i]:
                last_applied_manifest[i] = response_field
        else:
            # If the current field in the response is not in the last_applied_manifest, then add it to the end of the list
            last_applied_manifest.append(response_field)
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
